const express = require('express');
const helmet = require('helmet');
const nodemailer = require('nodemailer');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// Feature flag configuration
const featureFlags = {
  ENHANCED_SECURITY_HEADERS: process.env.ENHANCED_SECURITY_HEADERS || 'true',
  RATE_LIMITING: process.env.RATE_LIMITING || 'true',
  EMAIL_TEMPLATES_V2: process.env.EMAIL_TEMPLATES_V2 || 'false',
  FRAME_GUARD_MODE: process.env.FRAME_GUARD_MODE || 'sameorigin',
  CSP_REPORT_ONLY: process.env.CSP_REPORT_ONLY || 'false'
};

function isFeatureEnabled(flag) {
  const val = featureFlags[flag];
  // Support boolean-like strings and truthy checks
  if (typeof val === 'string') {
    return val.toLowerCase() !== 'false' && val !== '0' && val !== '';
  }
  return Boolean(val);
}

// Security middleware layer
function applySecurityHeaders(req, res, next) {
  if (isFeatureEnabled('ENHANCED_SECURITY_HEADERS')) {
    // Apply X-Frame-Options based on configured mode
    const frameMode = featureFlags.FRAME_GUARD_MODE;
    res.setHeader('X-Frame-Options', frameMode.toUpperCase());

    // Build CSP header
    const cspDirectives = [
      "default-src 'self'",
      "script-src 'self'",
      "style-src 'self' 'unsafe-inline'",
      "img-src 'self' data:"
    ];

    // frame-ancestors directive based on feature flag
    const cspReportOnly = isFeatureEnabled('CSP_REPORT_ONLY');
    cspDirectives.push("frame-ancestors 'self'");

    const cspHeader = cspReportOnly 
      ? 'Content-Security-Policy-Report-Only' 
      : 'Content-Security-Policy';
    res.setHeader(cspHeader, cspDirectives.join('; '));
  }

  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
}

app.use(applySecurityHeaders);

// Email transport configuration
const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || 'localhost',
  port: parseInt(process.env.SMTP_PORT || '587'),
  secure: true,
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS
  }
});

// In-memory session store (simplified)
const sessions = new Map();

// Authentication middleware
async function authenticate(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || !sessions.has(sessionId)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = sessions.get(sessionId);
  next();
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }
  // Simplified auth - in production would check DB
  const storedHash = process.env.ADMIN_PASS_HASH;
  if (email === process.env.ADMIN_EMAIL && storedHash) {
    try {
      if (await argon2.verify(storedHash, password)) {
        const sessionId = crypto.randomBytes(32).toString('hex');
        sessions.set(sessionId, { email, role: 'admin' });
        return res.json({ sessionId });
      }
    } catch (e) {
      // timing-safe failure
    }
  }
  return res.status(401).json({ error: 'Invalid credentials' });
});

// Email sending endpoint
app.post('/api/send-email', authenticate, async (req, res) => {
  const { to, subject, body } = req.body;

  if (!to || !subject || !body) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(to)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  try {
    await transporter.sendMail({
      from: process.env.FROM_EMAIL || 'noreply@example.com',
      to,
      subject,
      text: body
    });
    res.json({ success: true, message: 'Email sent' });
  } catch (err) {
    res.status(500).json({ error: 'Failed to send email' });
  }
});

// Dashboard page (serves HTML for email management UI)
app.get('/dashboard', authenticate, (req, res) => {
  res.setHeader('Content-Type', 'text/html');
  res.send(`<!DOCTYPE html><html><head><title>Email Dashboard</title></head><body><h1>Email Service Dashboard</h1><form id="emailForm" action="/api/send-email" method="POST"><input name="to" placeholder="Recipient"/><input name="subject" placeholder="Subject"/><textarea name="body"></textarea><button type="submit">Send</button></form></body></html>`);
});

app.listen(3000, () => {
  console.log('Email service running on port 3000');
});

module.exports = app;
